Here is a JavaScript code that creates a pendulum applet using HTML5 Canvas and allows the user to input the initial angle and releases the pendulum when a button is clicked:
```
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>Pendulum Simulator</title>
  <style>
    #canvas {
      border: 1px solid black;
    }
  </style>
</head>
<body>
  <h1>Pendulum Simulator</h1>
  <input id="initial-angle" type="number" value="45">
  <button id="release-button">Release Pendulum</button>
  <canvas id="canvas" width="400" height="400"></canvas>

  <script>
    // Constants
    const G = 9.81; // gravitational constant
    const M = 1; // mass of the pendulum bob
    const L = 100; // length of the pendulum
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');
    const angle = parseFloat(document.getElementById('initial-angle').value);
    let omega = 0;
    let theta = angle * Math.PI / 180;
    let dt = 0.01; // time step
    let timer = 0;

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.beginPath();
      ctx.arc(canvas.width / 2, canvas.height / 2, L, 0, 2 * Math.PI);
      ctx.fillStyle = 'black';
      ctx.fill();
      ctx.beginPath();
      ctx.arc(canvas.width / 2 + L * Math.sin(theta), canvas.height / 2 - L * Math.cos(theta), 10, 0, 2 * Math.PI);
      ctx.fillStyle = 'red';
      ctx.fill();
      ctx.beginPath();
      ctx.arc(canvas.width / 2, canvas.height / 2, 5, 0, 2 * Math.PI);
      ctx.fillStyle = 'black';
      ctx.fill();
    }

    function update() {
      omega += (-G * M * Math.sin(theta)) / L;
      theta += omega * dt;
      if (theta > Math.PI / 2 || theta < -Math.PI / 2) {
        omega = 0;
        theta = angle * Math.PI / 180;
      }
    }

    function animate() {
      requestAnimationFrame(animate);
      update();
      draw();
      timer++;
      if (timer > 1000) {
        stop();
      }
    }

    function release() {
      timer = 0;
      omega = 0;
      theta = angle * Math.PI / 180;
      animate();
    }

    function stop() {
      cancelAnimationFrame(animate);
    }

    document.getElementById('release-button').addEventListener('click', release);

    draw();
  </script>
</body>
</html>
```
This code creates a HTML5 Canvas element and uses it to draw the pendulum. The `draw()` function clears the canvas and draws the pendulum at its initial position. The `update()` function updates the angle and angular velocity of the pendulum based on the physics laws of gravity and the initial conditions. The `animate()` function calls `update()` and `draw()` repeatedly to simulate the pendulum's motion. The `release()` function is called when the user clicks the button, and it sets the timer to 0 and the initial conditions for the pendulum. The `stop()` function is called when the pendulum's motion stops, and it cancels the animation.

