  <title>Round-Robin URL Routing Example</title>
  <script>
    // Set the host and API endpoint URL
    const host = 'https://example.com';
    const apiEndpoint = '/url-counter';

    // Set the 10 different fixed sets of URLs
    const urls = [
      'https://www.example1.com',
      'https://www.example2.com',
      'https://www.example3.com',
      'https://www.example4.com',
      'https://www.example5.com',
      'https://www.example6.com',
      'https://www.example7.com',
      'https://www.example8.com',
      'https://www.example9.com',
      'https://www.example10.com'
    ];

    // Initialize the URL counter and the current URL index
    let counter = 0;
    let currentIndex = 0;

    // Get the URL counter value from the API
    fetch(`${host}${apiEndpoint}`)
      .then(response => response.json())
      .then(data => {
        counter = data.counter;
      })
      .catch(error => console.error(error));

    // Set the initial URL and URL index
    const initialUrl = urls[currentIndex];
    const initialAnchor = document.getElementById('anchor');
    initialAnchor.href = initialUrl;
    initialAnchor.textContent = initialUrl;

    // Update the URL and URL index every 5 seconds
    setInterval(() => {
      currentIndex = (currentIndex + 1) % urls.length;
      counter++;

      // Send the updated counter value to the API
      fetch(`${host}${apiEndpoint}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ counter })
      });

      // Get the new URL and update the anchor
      const newUrl = urls[currentIndex];
      const newAnchor = document.getElementById('anchor');
      newAnchor.href = newUrl;
      newAnchor.textContent = newUrl;
    }, 5000);
  </script>
</head>
<body>
  <a id="anchor"></a>
</body>
</html>
```
