import { Controller, Post, Body, SetCookieHeader, Req, Res } from '@nestjs/common';
import { UserService } from './user.service';
import * as jwt from 'jsonwebtoken';

@Controller('auth')
export class AuthController {
  constructor(private readonly userService: UserService) {}

  @Post('login')
  async login(@Body() credentials: any, @Req() req: Request, @Res() res: Response) {
    const user = await this.userService.validateUser(credentials);
    if (!user) {
      return res.status(401).json({ message: 'Invalid credentials' });
    }

    const token = this.generateJwtToken(user);

    res.cookie('jwt-token', token, {
      httpOnly: true,
      secure: true,
      sameSite: 'strict',
      maxAge: 3600000, // 1 hour
    });

    res.json({ message: 'Logged in successfully' });
  }

  private generateJwtToken(user: any) {
    const payload = { sub: user.id, email: user.email };
    return jwt.sign(payload, 'YOUR_SECRET_KEY', { expiresIn: '1h' });
  }
}
