```
#include <iostream>
#include <fstream>
#include <filesystem>
#include <string>
#include <vector>
#include <algorithm>

// Function to sort files by creation time
struct cmp {
    bool operator()(const std::filesystem::directory_entry& a, const std::filesystem::directory_entry& b) {
        return a.last_write_time() < b.last_write_time();
    }
};

int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <folder_path>" << std::endl;
        return 1;
    }

    std::string folderPath = argv[1];
    if (!std::filesystem::exists(folderPath)) {
        std::cerr << "Folder does not exist: " << folderPath << std::endl;
        return 1;
    }

    std::vector<std::filesystem::directory_entry> files;
    for (const auto& entry : std::filesystem::directory_iterator(folderPath)) {
        if (entry.is_regular_file()) {
            files.push_back(entry);
        }
    }

    // Sort files by creation time
    std::sort(files.begin(), files.end(), cmp());

    int count = 0;
    for (const auto& file : files) {
        std::string newName = "FILE_" + std::to_string(count++).substr(1, 3) + ".txt";
        std::filesystem::rename(file.path(), folderPath + "/" + newName);
        std::cout << "Renamed " << file.path().string() << " to " << folderPath + "/" + newName << std::endl;
    }

    return 0;
}
```
