```
pragma solidity ^0.8.0;

contract FixedSupplyNFT {
    // Mapping of NFTs to their owners
    mapping(uint256 => address) public nftOwners;

    // Array of all NFTs in the collection
    NFT[] public nfts;

    // Total supply of NFTs
    uint256 public totalSupply;

    // Event emitted when an NFT is minted
    event Mint(address indexed owner, uint256 indexed nftId);

    // Event emitted when an NFT is transferred
    event Transfer(address indexed from, address indexed to, uint256 indexed nftId);

    // Event emitted when the NFT collection is updated
    event Update(address indexed owner, uint256 indexed nftId, uint256 ttl);

    // Function to mint a new NFT
    function mint() public {
        // Check if the total supply has not been reached
        require(totalSupply < nfts.length, "The total supply of NFTs has been reached.");

        // Get the next available NFT ID
        uint256 nftId = nfts.length++;

        // Set the owner of the new NFT
        nftOwners[nftId] = msg.sender;

        // Emit the Mint event
        emit Mint(msg.sender, nftId);

        // Update the total supply
        totalSupply++;
    }

    // Function to transfer an NFT
    function transfer(uint256 _nftId, address _to) public {
        // Check if the NFT exists and the owner is transferring the NFT
        require(nftOwners[_nftId] == msg.sender, "You are not the owner of this NFT.");

        // Update the owner of the NFT
        nftOwners[_nftId] = _to;

        // Emit the Transfer event
        emit Transfer(msg.sender, _to, _nftId);
    }

    // Constructor function
    constructor() public {
        // Initialize the total supply and the array of NFTs
        totalSupply = 0;
        nfts = new NFT[](10); // Replace with the total supply of NFTs

        // Initialize the NFT IDs and owners
        for (uint256 i = 0; i < nfts.length; i++) {
            nftOwners[i] = address(0); // Set the owner to 0, indicating it's not minted yet
        }
    }
}
```
Here's an explanation of the code:

* The `nftOwners` mapping stores the owner of each NFT, where the key is the NFT ID and the value is the owner's address.
