import android.widget.Adapter;
import android.widget.AdapterView;
import android.widget.ArrayAdapter;
import android.widget.ListView;
import android.widget.Toast;

import java.util.ArrayList;

public class ShopActivity extends Activity {
    private static final String TAG = "ShopActivity";
    private static final String DB_NAME = "shop.db";
    private static final String TABLE_NAME = "items";
    private static final String COLUMN_ID = "_id";
    private static final String COLUMN_NAME = "name";
    private static final String COLUMN قیمت = "price";

    private SQLiteDatabase db;
    private ListView listView;
    private ArrayList<String> items;
    private ArrayAdapter<String> adapter;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_shop);

        listView = findViewById(R.id.listView);
        items = new ArrayList<>();

        // Open the database
        db = new DatabaseHelper(this).getWritableDatabase();

        // Fill the list with existing items (if any)
        Cursor cursor = db.query(TABLE_NAME, null, null, null, null, null, null);
        if (cursor.moveToFirst()) {
            do {
                items.add(cursor.getString(cursor.getColumnIndex(COLUMN_NAME)));
            } while (cursor.moveToNext());
        }
        cursor.close();

        // Create and set the adapter
        adapter = new ArrayAdapter<>(this, android.R.layout.simple_list_item_1, items);
        listView.setAdapter(adapter);

        // Set the list view item click listener
        listView.setOnItemClickListener(new AdapterView.OnItemClickListener() {
            @Override
            public void onItemClick(AdapterView<?> parent, View view, int position, long id) {
                // Open the item edit activity
                Intent intent = new Intent(ShopActivity.this, ItemEditActivity.class);
                intent.putExtra("id", items.get(position));
                startActivityForResult(intent, 1);
            }
        });

        // Set the list view item long click listener
        listView.setOnItemLongClickListener(new AdapterView.OnItemLongClickListener() {
            @Override
            public boolean onItemLongClick(AdapterView<?> parent, View view, int position, long id) {
                // Delete the item
                db.delete(TABLE_NAME, COLUMN_ID + "=?", new String[]{String.valueOf(id)});
                items.remove(position);
                adapter.notifyDataSetChanged();
                return true;
            }
        });
    }

    @Override
    protected void onActivityResult(int requestCode, int resultCode, Intent data) {
        super.onActivityResult(requestCode, resultCode, data);
        if (requestCode == 1) {
            if (resultCode == RESULT_OK) {
                // Update the list with the modified item
                items.set(getItemIndex(data.getStringExtra("id")), data.getStringExtra("name"));
                adapter.notifyDataSetChanged();
            }
        }
    }

    private int getItemIndex(String id) {
        for (int i = 0; i < items.size(); i++) {
            if (items.get(i).equals(id)) {
                return i;
            }
        }
        return -1;
    }

    public void addItem(View view) {
        // Open the item add activity
        Intent intent = new Intent(ShopActivity.this, ItemAddActivity.class);
        startActivityForResult(intent, 2);
    }
}
