  // Send a request to the server to reject the claim
  fetch(`/rejectClaim/${claimId}`, {
    method: "PUT",
  })
    .then((response) => response.json())
    .then((data) => {
      // If the claim was rejected successfully, display a success message
      alert("Claim rejected successfully!");
    })
    .catch((error) => {
      // If there was an error rejecting the claim, display an error message
      alert(`Error rejecting claim: ${error}`);
    });
}

// Create a table to display the claims
