% Define the target position of the end-effector
x_target = [0.5; 0.5; pi/4];  % target position (m, m, rad)

% Define the feedback control gains
Kp = [1, 1];  % proportional gain (N*m^-1, N*m^-1)
Kd = [0.1, 0.1];  % derivative gain (s^-1, s^-1)

% Define the simulation time and time step
