Here's an example of how you can achieve this:
```jsx
import { useLocation, useNavigate } from 'react-router-dom';
import { SyntheticEvent } from 'react';
import { TankStackTable } from 'react-tanstack-table';

const Table = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const [columnFilters, setColumnFilters] = useState({});

  const handleFilterChange = (column: string, value: any) => {
    setColumnFilters((prevFilters) => ({ ...prevFilters, [column]: value }));
  };

  useEffect(() => {
    const queryParams = new URLSearchParams(location.search);
    const currentFilters = queryParams.getAll('filter');

    if (!currentFilters || currentFilters.length === 0) {
      return;
    }

    const filteredFilters = currentFilters.reduce((acc, filter) => {
      const [column, value] = filter.split(':');
      acc[column] = JSON.parse(value);
      return acc;
    }, {});

    setColumnFilters(filteredFilters);
  }, [location.search]);

  const handleApplyFilters = () => {
    const queryParams = new URLSearchParams();
    Object.keys(columnFilters).forEach((column) => {
      queryParams.append(`filter`, `${column}:${JSON.stringify(columnFilters[column])}`);
    });

    navigate({ pathname: location.pathname, search: queryParams.toString() });
  };

  return (
    <TankStackTable
      data={[
        { column1: 'value1', column2: 'value2', column3: 'value3' },
        // ...
      ]}
      columns={[
        {
          columns: [
            {
              Header: 'Column 1',
              accessor: 'column1',
              filter: 'text',
              Filter: ({ filter }) => (
                <input
                  type="text"
                  value={filter.value}
                  onChange={(e) => handleFilterChange('column1', e.target.value)}
                />
              ),
            },
            // ...
          ],
        },
      ]}
      onApplyFilters={handleApplyFilters}
    />
  );
};
```
